const system =
  "You answer only questions about our return policy.\n" +
  "REFUSAL RULE: If the request is outside return policy, or asks for advice you\n" +
  "cannot ground in the policy, output EXACTLY: REFUSE: <one-line reason>\n" +
  "and nothing else. Do NOT guess.";

// The code can now act on the contract:
function route(output) {
  if (output.startsWith("REFUSE:")) {
    return { kind: "refused", reason: output.slice("REFUSE:".length).trim() };
  }
  return { kind: "answer", text: output };
}

