decomposition-chaining.code:
// Mega-prompt: one call does extraction AND transformation, opaque on failure.
const mega = "From the text, extract the amounts, sum them, and format as USD: " + text;

// Chain: step 1 extracts (validate!), step 2 transforms the validated data.
async function chain(text) {
  const nums = await extractAmounts(text);          // step 1
  if (!Array.isArray(nums) || nums.some(n => typeof n !== "number"))
    throw new Error("extract step produced invalid data — stop the chain");  // validated hand-off
  const total = await formatUSD(nums);              // step 2 sees only clean input
  return total;
}

decomposition-chaining.starter:
// Guard every hand-off in a three-stage chain
// Mission: Break a complex request into a CHAIN of small, single-purpose prompts where each step's validated output feeds the next — instead of asking one mega-prompt to do everything at once.
// Evidence checklist:
// 1. Each step is single-purpose and independently testable.
// 2. Every intermediate is validated before it feeds the next step.
// 3. A failed validation stops the chain and names the failing stage.
// 4. A malformed intermediate never reaches or corrupts a later step.
// Novice workflow: predict, implement the TODO, run every fixture, add a failing case, retain it as a regression.
// Local execution is practice feedback only; it cannot create mastery evidence.

// Three stages run in order; each hand-off is validated before the next stage runs.
// A stage returns null to reject its input. Stop at the first rejecting stage and name it.
const stages = [
  { name: "parse",    run: (s) => s.split(",").map((x) => Number(x.trim())) },
  { name: "positive", run: (xs) => xs.every((n) => Number.isFinite(n) && n > 0) ? xs : null },
  { name: "sum",      run: (xs) => xs.reduce((a, n) => a + n, 0) },
];
function runChain(input, stages) {
