chain-of-thought.code:
// CoT that stays OUT of the parsed result: reason, then emit a delimited answer.
const prompt =
  "Solve the problem. Think step by step INSIDE <reasoning></reasoning>.\n" +
  "Then give ONLY the final answer inside <answer></answer>.\n" +
  "Problem: A train travels 60km in 1.5h then 40km in 0.5h. Average speed?";

// Parser takes the fenced answer and ignores the scratch work:
function finalAnswer(out) {
  const m = out.match(/<answer>([\s\S]*?)<\/answer>/);
  return m ? m[1].trim() : null;   // the reasoning never reaches downstream code
}

