// Vacuous: nothing concrete to verify, usually a no-op.
const bad = "Here is the copy. Is it good? If not, fix it.";

// Criteria-driven critique → targeted revision:
const RULES = [
  { name: "length", test: s => s.split(/\s+/).length <= 20 },
  { name: "no-competitor", test: s => !/acme/i.test(s) },
  { name: "has-cta", test: s => /\b(buy|try|start)\b/i.test(s) },
];
function critique(draft) {
  const results = RULES.map(r => ({ name: r.name, pass: r.test(draft) }));
  const failed = results.filter(r => !r.pass).map(r => r.name);
  return { pass: failed.length === 0, failed, results };
}

self-check-critique.starter:
// Run the bounded critique-and-revise loop
// Mission: Add a second pass that CHECKS the first answer against explicit criteria and revises it — turning a one-shot generation into generate → critique → revise, with the critique verifying concrete rules rather than "looking again".
// Evidence checklist:
// 1. It checks explicit, per-rule criteria, not a global "is this good?".
// 2. Crisp rules are verified in code; the model judges only fuzzy criteria.
// 3. The revision targets the specific failed rules.
// 4. The loop has a max-iteration cap so it always terminates.
// Novice workflow: predict, implement the TODO, run every fixture, add a failing case, retain it as a regression.
// Local execution is practice feedback only; it cannot create mastery evidence.

// Each rule has a test AND a targeted fix. Loop: find the FIRST failing rule,
// apply its fix, re-check — bounded by maxIters so a critique loop cannot run forever.
const RULES = [
  { name: "no-competitor", test: (s) => !/acme/i.test(s), fix: (s) => s.replace(/acme/gi, "our product") },
  { name: "has-cta",       test: (s) => /\b(try|start)\b/i.test(s), fix: (s) => s + " — start today" },
];
function reviseUntilClean(draft, rules, maxIters) {
  // TODO: implement the prompt decision against every supplied fixture.
  throw new Error("complete the prompt evidence decision");
}
const r = reviseUntilClean("Switch from Acme to save", RULES, 5);
console.log("final:", r.final);
console.log("iterations:", r.iterations);
console.log("clean:", r.clean);

