// Schema-constrained (mirrors strict json_schema mode):
const schema = {
  fields: { id: "string", total: "number" },
  required: ["id", "total"],
  additional: false,          // no extra keys — like additionalProperties:false
};
function validate(obj, schema) {
  const errs = [];
  for (const k of schema.required) if (!(k in obj)) errs.push("missing " + k);
  for (const [k, t] of Object.entries(schema.fields))
    if (k in obj && typeof obj[k] !== t) errs.push(k + " must be " + t);
  if (!schema.additional)
    for (const k of Object.keys(obj)) if (!(k in schema.fields)) errs.push("unexpected " + k);
  return { valid: errs.length === 0, errs };
}

