// Same prompt, same eval set, two model versions → compare per case.
function detectDrift(oldResults, newResults) {   // arrays of { case, pass } aligned by case
  const flipsToFail = [];
  let oldPass = 0, newPass = 0;
  for (let i = 0; i < oldResults.length; i++) {
    if (oldResults[i].pass) oldPass++;
    if (newResults[i].pass) newPass++;
    if (oldResults[i].pass && !newResults[i].pass) flipsToFail.push(oldResults[i].case);
  }
  return {
    oldRate: oldPass / oldResults.length,
    newRate: newPass / newResults.length,
    regressedCases: flipsToFail,      // the localized drift
  };
}

