const READ_ONLY = new Set(["search_docs", "get_policy"]);   // least-privilege allowlist
const HIGH_RISK = new Set(["send_email", "delete_record", "issue_refund"]);

function defend(untrustedInput, proposedAction) {
  // Layer 1: segregate untrusted content as data (from Module 3).
  const safe = "<data>" + untrustedInput.replace(/[<>]/g, "") + "</data>";
  // Layer 2: least-privilege — only allowlisted tools may run autonomously.
  if (!READ_ONLY.has(proposedAction) && !HIGH_RISK.has(proposedAction))
    return { decision: "deny", reason: "tool not permitted" };
  // Layer 3: high-risk actions require human approval, never autonomous.
  if (HIGH_RISK.has(proposedAction))
    return { decision: "needs_human", reason: "high-risk action requires approval" };
  return { decision: "allow", safe };
}

