const DISALLOWED = ["weapon_synthesis", "malware", "self_harm_method"];
function classifyIntent(text) {                 // maps request to an intent label
  if (/synthesi[sz]e|make .*(explosive|nerve agent)/i.test(text)) return "weapon_synthesis";
  if (/write .*(ransomware|keylogger)/i.test(text)) return "malware";
  return "benign";
}
