function pipeline(request) {
  const report = { version: "v3", steps: {} };
  // 1. segregate untrusted input as data (Module 3)
  const safe = "<data>" + request.userText.replace(/[<>]/g, "") + "</data>";
  // 2. injection screen (Module 5)
  report.steps.injection = /ignore .*instructions/i.test(request.userText) ? "flagged" : "clean";
  // 3. model output → schema validate (Module 3)
  const out = request.modelOut;                         // { action, amount }
  report.steps.schema = (typeof out.action === "string" && typeof out.amount === "number") ? "valid" : "invalid";
  // 4. eval score vs expectation (Module 4)
  report.steps.eval = out.action === request.expectedAction ? "pass" : "fail";
  // 5. least-privilege + human approval (Module 5)
  const HIGH_RISK = new Set(["issue_refund", "delete"]);
  report.steps.action = HIGH_RISK.has(out.action) ? "needs_human" : "auto";
  return report;
}

